import{_ as o,c as t,o as n,ai as r}from"./chunks/framework.D1sNzFSI.js";const m=JSON.parse('{"title":"OCM v2: A Fresh Foundation for Secure Software Delivery","description":"","frontmatter":{"title":"OCM v2: A Fresh Foundation for Secure Software Delivery","date":"2026-08-03","banner":"assets/blog/20260803_ocm_v2_release_banner.svg","authors":["open-component-model-team"],"tags":["2026","news","projects","ocm"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"BlogEntryThemeComponent"},"headers":[],"relativePath":"blog/20260803_ocm_v2_release.md","filePath":"blog/20260803_ocm_v2_release.md"}'),a={name:"blog/20260803_ocm_v2_release.md"};function i(s,e,l,c,h,d){return n(),t("div",null,e[0]||(e[0]=[r('<h1 id="ocm-v2-a-fresh-foundation-for-secure-software-delivery" tabindex="-1">OCM v2: A Fresh Foundation for Secure Software Delivery <a class="header-anchor" href="#ocm-v2-a-fresh-foundation-for-secure-software-delivery" aria-label="Permalink to &quot;OCM v2: A Fresh Foundation for Secure Software Delivery&quot;">​</a></h1><p>The <a href="https://ocm.software/" target="_blank" rel="noreferrer">Open Component Model (OCM)</a> project, part of NeoNephos, has released <strong>OCM v2</strong>: a ground-up rebuild of its tooling stack, a new CLI, Kubernetes controllers, and Go bindings, all designed from the start for modularity, security, and community contribution. The full announcement is on the <a href="https://ocm.software/blog/ocmv2/" target="_blank" rel="noreferrer">OCM blog</a>; this is the short version for the NeoNephos community.</p><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><p>The original OCM libraries served the project well, but a monolithic architecture pulled in more than most users needed, was hard for new contributors to navigate, and made every change risk regressions elsewhere. OCM v2 answers that with a modular design, decoupled APIs, and a smaller dependency footprint. All three components, the CLI, the Kubernetes controllers, and the Go bindings, now live in a <a href="https://github.com/open-component-model/open-component-model" target="_blank" rel="noreferrer">single monorepo</a>, sharing one dependency tree and release cycle.</p><p>The full <strong>Pack, Sign, Transport, Deploy</strong> workflow is covered end to end: bundle software into component versions, sign them for provenance, move them between registries or across air gaps, and deploy them to Kubernetes via GitOps-native controllers. Every version created with v2 still implements the <a href="https://github.com/open-component-model/ocm-spec" target="_blank" rel="noreferrer">OCM Specification v2</a>, so it stays fully interoperable with the existing stack.</p><p>A significant step forward is <strong>native OCI compatibility</strong>: component versions are now stored as standard OCI Image Indices, so a Helm chart or container image packaged in an OCM component can be pulled directly with <code>helm pull</code> or <code>docker pull</code>, no OCM-specific tooling in the path.</p><h2 id="a-community-reboot-within-neonephos" tabindex="-1">A community reboot within NeoNephos <a class="header-anchor" href="#a-community-reboot-within-neonephos" aria-label="Permalink to &quot;A community reboot within NeoNephos&quot;">​</a></h2><p>OCM v2 is not only a technical reboot. Since OCM joined NeoNephos, the project has established open governance: the <strong>OCM Technical Steering Committee</strong> sets the strategic direction, and a dedicated <strong>SIG Spec</strong> for the specification itself is in preparation.</p><h2 id="sig-runtime" tabindex="-1">SIG Runtime <a class="header-anchor" href="#sig-runtime" aria-label="Permalink to &quot;SIG Runtime&quot;">​</a></h2><p>The runtime has a dedicated home: <strong><a href="https://github.com/open-component-model/open-component-model/blob/main/docs/community/SIGs/Runtime/SIG-Runtime-CHARTER.md" target="_blank" rel="noreferrer">SIG Runtime</a></strong>, the special interest group that maintains and shapes the OCM runtime: the Go bindings, the CLI, and the Kubernetes controllers. Its goal is to keep OCM components creatable, signable, transportable, verifiable, and deployable. Technical decisions are tracked openly through <a href="https://github.com/open-component-model/open-component-model/tree/main/docs/adr" target="_blank" rel="noreferrer">ADRs</a>, and the SIG reports to the OCM Technical Steering Committee.</p><h2 id="get-involved" tabindex="-1">Get involved <a class="header-anchor" href="#get-involved" aria-label="Permalink to &quot;Get involved&quot;">​</a></h2><ul><li>Read the <a href="https://ocm.software/blog/ocmv2/" target="_blank" rel="noreferrer">full announcement</a> and the <a href="https://ocm.software/docs/" target="_blank" rel="noreferrer">documentation</a></li><li>Browse and contribute on <a href="https://github.com/open-component-model/open-component-model" target="_blank" rel="noreferrer">GitHub</a></li><li>Join the conversation on Zulip: <a href="https://linuxfoundation.zulipchat.com/#narrow/channel/532975-neonephos-ocm-support" target="_blank" rel="noreferrer">neonephos-ocm-support</a></li></ul><p>We are looking forward to building the future of sovereign cloud delivery together.</p>',13)]))}const u=o(a,[["render",i]]);export{m as __pageData,u as default};
